import {
    SORT_ORDER
} from "./const";
export const reverseSortOrder = sortOrder => sortOrder === SORT_ORDER.descending ? SORT_ORDER.ascending : SORT_ORDER.descending;
export const shouldCancelDragging = (field, targetGroup) => {
    if (!field) {
        return false
    }
    if (true === field.isMeasure) {
        return "column" === targetGroup || "row" === targetGroup || "filter" === targetGroup
    }
    if (false === field.isMeasure && "data" === targetGroup) {
        return true
    }
    return false
};
